mapper.select:
select case_id, subject_user_id, source_report_id, violation_type, severity,
       status, description, evidence, handler_id, resolved_time,
       create_time, update_time
from lf_violation_case

    status = #{status}
    and severity = #{severity}
    and subject_user_id = #{subjectUserId}

order by create_time desc, case_id desc

select action_id, case_id, user_id, action_type, scope, start_time,
       end_time, reason, operator_id, create_time
from lf_violation_action

    user_id = #{userId}
    and action_type = #{actionType}
    and scope = #{scope}

order by create_time desc, action_id desc

mapper.update:
update lf_violation_action
set end_time = #{endTime}
where action_id = #{actionId}
  and user_id = #{userId}
